from pathlib import Path
import re,hashlib
root=Path(__file__).resolve().parents[2];p=root/'windows/src';original=(p/'Renderer.cpp').read_text('utf-8');s=original
s=re.sub(r'    if \(hasHdr\(s\)\) return [^\n]+\n','',s)
s=re.sub(r'    if \(s.bitDepth == 16\)\n        return [^\n]+\n','',s)
s=re.sub(r'    if \(wideImage\(l.mask\) \|\| wideImage\(l.image\)\)\n        return [^\n]+\n','',s)
for name in ('render','renderMask','layerSurface','blendPixel'):
 s=re.sub(r'\b'+name+r'\b',name+'Hdr',s)
s=s.replace('QImage::Format_ARGB32_Premultiplied','QImage::Format_RGBA32FPx4_Premultiplied').replace('QRgb','FloatPixel')
for a,b in [('qRed','floatRed'),('qGreen','floatGreen'),('qBlue','floatBlue'),('qAlpha','floatAlpha'),('qRgba','floatRgba'),('qRound','floatRound')]:s=s.replace(a+'(',b+'(')
s=s.replace('std::array<int, 3> result;','std::array<double, 3> result;').replace('const int alpha =','const double alpha =')
s=s.replace('std::clamp(floatRound(((1 - as) * ab * b[c] + (1 - ab) * as * s[c] + ab * as * blend[c]) * 255), 0, alpha)','((1 - as) * ab * b[c] + (1 - ab) * as * s[c] + ab * as * blend[c])')
s=re.sub(r'\b255\b','1',s)
s=s.replace('bool nativeMode(const QString &mode, QPainter::CompositionMode &out) {','bool nativeMode(const QString &mode, QPainter::CompositionMode &out) {\n    Q_UNUSED(mode);Q_UNUSED(out);return false;')
s=s.replace('QColor(0, 0, 0, floatRound(l.opacity * 1))','coverageColor(l.opacity)').replace('QColor(0, 0, 0, floatRound(groupOpacity * 1))','coverageColor(groupOpacity)')
s=s.replace('l.mask.convertToFormat(QImage::Format_Grayscale8)','maskImage(l.mask,16)').replace('const auto *src = gray.constScanLine(y);','const auto *src = reinterpret_cast<const quint16 *>(gray.constScanLine(y));').replace('floatRgba(src[x], src[x], src[x], src[x])','floatRgba(src[x]/65535., src[x]/65535., src[x]/65535., src[x]/65535.)')
s='#include "Hdr.h"\n'+s
(p/'HdrRenderer.cpp').write_text('// Generated by windows/scripts/generate-hdr-renderer.py.\n// Source SHA256: '+hashlib.sha256(original.encode()).hexdigest()+'\n'+s,'utf-8')
